assert sum(1 for a,b in cp if {a[1],b[1]}=={'П','Ч'})==81 and sum(1 for a,b in cp if (a[0]=='К' and b[1]=='П') or (b[0]=='К' and a[1]=='П'))==35 and sum(1 for a,b in cp if a[1]==b[1])==144
